// Resolves bare module specifiers against the chromium-bidi `node_modules`
// folder when the default resolution fails. The build output (for example
// `out/Default/gen/third_party/chromium-bidi`) is not a descendant of the
// chromium-bidi directory in a Chromium checkout. This hook makes it possible
// to run the compiled files without a symlink or a copy of `node_modules` in
// the out directory.
//
// Usage: node --import <file URL of this file> ...

import {registerHooks} from 'node:module';
import * as path from 'node:path';
import {pathToFileURL} from 'node:url';

const bidiRoot = path.dirname(import.meta.dirname);
const packageJsonURL = pathToFileURL(path.join(bidiRoot, 'package.json')).href;

registerHooks({
  resolve(specifier, context, nextResolve) {
    try {
      return nextResolve(specifier, context);
    } catch (err) {
      if (
        !specifier.startsWith('.') &&
        !specifier.startsWith('/') &&
        !specifier.startsWith('node:')
      ) {
        return nextResolve(specifier, {
          ...context,
          parentURL: packageJsonURL,
        });
      }
      throw err;
    }
  },
});
